import React from 'react';

export interface HttpApiClientProps {
  base_url: string;
  timeout_ms?: number;
  max_retries?: number;
  auth_token?: string;
  onRequestStarted?: (payload: { method: 'GET' | 'POST'; path: string }) => void;
  onRequestSucceeded?: (payload: { status: number; duration_ms: number }) => void;
  onRequestFailed?: (payload: { reason: 'timeout' | 'network' | 'http_4xx' | 'http_5xx'; status: number }) => void;
}

const HttpApiClient: React.FC<HttpApiClientProps> = ({
  base_url,
  timeout_ms = 10000,
  max_retries = 3,
  auth_token,
}) => {
  return (
    <div data-component="HttpApiClient">
      <div>base_url: {base_url}</div>
      <div>timeout_ms: {timeout_ms}</div>
      <div>max_retries: {max_retries}</div>
      <div>auth_token: {auth_token ? 'set' : 'unset'}</div>
    </div>
  );
};

export default HttpApiClient;
